ALTER TABLE channel_identities ADD COLUMN bot_key text, ADD COLUMN external_chat_id text, ADD COLUMN status text NOT NULL DEFAULT 'active';
ALTER TABLE channel_identities ADD CONSTRAINT channel_identities_status_check CHECK (status IN ('active','unresolved','blocked'));
ALTER TABLE channel_identities DROP CONSTRAINT IF EXISTS channel_identities_provider_external_unique;
DROP INDEX IF EXISTS channel_identities_provider_external_legacy_unique;
CREATE UNIQUE INDEX channel_identities_provider_external_legacy_unique ON channel_identities(provider, external_id) WHERE bot_key IS NULL;
CREATE UNIQUE INDEX channel_identities_telegram_bot_user_chat_unique ON channel_identities(provider, bot_key, external_id, external_chat_id) WHERE provider = 'telegram' AND bot_key IS NOT NULL AND external_chat_id IS NOT NULL AND status = 'active';
CREATE TABLE "dialogues" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "tenant_key" text NOT NULL, "user_id" uuid NOT NULL REFERENCES "users"("id"), "provider" text NOT NULL, "bot_key" text NOT NULL, "external_chat_id" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "dialogues_scope_unique" UNIQUE(tenant_key, provider, bot_key, external_chat_id));
CREATE TABLE "dialogue_inbound" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "dialogue_id" uuid NOT NULL REFERENCES dialogues(id), "provider" text NOT NULL, "bot_key" text NOT NULL, "provider_update_id" bigint NOT NULL, "payload_hash" char(64) NOT NULL, "text" text NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, CONSTRAINT "dialogue_inbound_provider_bot_update_unique" UNIQUE(provider, bot_key, provider_update_id), CONSTRAINT "dialogue_inbound_text_check" CHECK (char_length(text) BETWEEN 1 AND 4096 AND text !~ '[[:cntrl:]]'), CONSTRAINT "dialogue_inbound_expiry_check" CHECK (expires_at = created_at + interval '30 days'));
CREATE TABLE "dialogue_route_decisions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "inbound_id" uuid NOT NULL REFERENCES dialogue_inbound(id), "route_version" integer NOT NULL DEFAULT 1, "route" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), CONSTRAINT "dialogue_route_check" CHECK (route IN ('deterministic','complex_dialogue')), CONSTRAINT "dialogue_route_version_check" CHECK (route_version > 0), CONSTRAINT "dialogue_route_inbound_unique" UNIQUE(inbound_id));
CREATE INDEX "dialogue_inbound_dialogue_idx" ON dialogue_inbound(dialogue_id, created_at);
CREATE INDEX "dialogue_inbound_expiry_idx" ON dialogue_inbound(expires_at, id);
